pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 hash1, bytes32 hash2) public {
        vm.assume(hash1 != bytes32(0));
        vm.assume(hash2 != bytes32(0));

        address user = address(0x1234);
        vm.deal(user, 2 ether);

        // First call - must succeed
        vm.prank(user);
        (bool success1,) = address(c).call{value: 1 ether}(abi.encodeWithSelector(c.lockInGuess.selector, hash1));
        assertTrue(success1, "First lockInGuess should succeed");

        // Second call from same user - in P it reverts, in M it succeeds
        vm.prank(user);
        (bool success2,) = address(c).call{value: 1 ether}(abi.encodeWithSelector(c.lockInGuess.selector, hash2));

        // Rule: Regardless of whether the second call reverts or not, the guess block must be non-zero
        // (because the first call set it, and if the second succeeded, it updated it)
        (uint256 blockNum,) = c.guesses(user);
        assertTrue(blockNum != 0, "guess block must be non-zero");
    }
}

