contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        vm.deal(address(this), 3 ether);
        uint256 guessBlock;
        {
            uint256 snapshot = vm.snapshot();
            c.lockInGuess{value: 1 ether}(hash);
