pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        vm.deal(address(this), 1 ether);
        vm.deal(address(c), 1 ether);
        c.lockInGuess{value: 1 ether}(hash);
        // Simulate block progression
        vm.roll(block.number + 2);
        // Record whether settle() would revert due to insufficient balance in the reference
        // In the reference, if balance < 2 ether and guess matches, it reverts via require
        // In the mutant, it would proceed but transfer would revert; the rule is that after lockInGuess,
        // settle() must not revert when the caller has a valid guess (i.e., the guess block is not 0 after settle)
        // We check that if settle() reverts, then either the guess did not match or balance was insufficient
        // Actually, the general rule: after lockInGuess, settle() either succeeds or reverts;
        // if it reverts, the guess block should remain non-zero (i.e., state unchanged)
        // But we cannot read guess block directly as it's private. Instead, we observe that in the reference,
        // a second call to settle() would also revert because the guess block is still non-zero.
        // In the mutant, if it reverts due to transfer failure, the guess block is still reset to 0.
        // So the rule: if settle() reverts, then a second call to settle() should also revert.
        // The mutant breaks this: first settle reverts (transfer fails) but resets guess block, so second settle would not revert.

        // First settle call
        (bool success1,) = address(c).call(abi.encodeWithSignature("settle()"));
        // Second settle call
        (bool success2,) = address(c).call(abi.encodeWithSignature("settle()"));
        // General rule: if the first settle reverted, the second must also revert (state unchanged).
        // In the reference, this holds. In the mutant, the first revert resets the guess block, so the second succeeds.
        assertTrue(!success1 || success2 == success1, "First revert should imply second revert");
    }
}

