pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // Fund the contract with initial balance for potential settlement
        payable(address(c)).transfer(2 ether);

        // Prepare caller with 1 ether for lockInGuess
        vm.deal(address(this), 1 ether);
        c.lockInGuess{value: 1 ether}(guess);

        // Record balance before settle
        uint256 balanceBefore = address(c).balance;

        // Warp to after the target block
        vm.roll(block.number + 2);

        // Compute what the answer should be (blockhash of block.number + 1)
        bytes32 expectedAnswer = blockhash(block.number - 1);
        bool guessMatches = (guess == expectedAnswer);

        // Attempt settle and check revert
        bool reverted = false;
        try c.settle() {
            if (guessMatches) {
                // If guess matches, balance should decrease by 2 ether
                assertTrue(address(c).balance == balanceBefore - 2 ether);
            } else {
                // If guess does not match, balance should remain unchanged
                assertTrue(address(c).balance == balanceBefore);
            }
        } catch {
            reverted = true;
        }

        // If it reverted, then it must be because guess did not match (insufficient balance check prevents transfer)
        if (reverted) {
            // The only way settle should revert is if the guess didn't match and balance is < 2 ether after guess matching case
            // In our scenario with 2 ether, it only reverts if balance condition fails, which happens only when guess matches (balance insufficient after transfer)
            // Actually with 2 ether balance and matching guess, it should succeed and transfer, so revert means guess didn't match
            assertTrue(!guessMatches);
        }
    }
}

